#!/bin/sh
# sampler.sh - per-cell host sampler: one TSV row every 0.5 s until killed.
# usage: sampler.sh <out.tsv> <measured-cpu> [ccd0-cpus ccd1-cpus]
# Columns: t_s, psi_cpu_some, psi_mem_some, psi_mem_full, psi_io_some, psi_io_full (avg10), mem_available_kb,
#          util_ccd0_pct, util_ccd1_pct (from /proc/stat deltas), freq_khz (scaling_cur_freq of the measured CPU).
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'live-host-measurement-confounds/sampler.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'sampler.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  echo "usage: sampler.sh <out.tsv> <measured-cpu> [ccd0-cpu-list ccd1-cpu-list]"
  echo "       sampler.sh --help | --build | --version"
  echo "Writes one TSV row every 0.5 s (PSI cpu/mem/io avg10, MemAvailable, per-CCD utilisation, measured-CPU frequency) until killed."
  exit 0
fi
set -eu


HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/ctl" --build ;;
esac
OUT=${1:?out file}; CPU=${2:?measured cpu}; C0=${3:-0-5,12-17}; C1=${4:-6-11,18-23}
printf 't_s\tpsi_cpu_some\tpsi_mem_some\tpsi_mem_full\tpsi_io_some\tpsi_io_full\tmem_avail_kb\tutil_ccd0\tutil_ccd1\tfreq_khz\n' >"$OUT"
exec awk -v out="$OUT" -v cpu="$CPU" -v c0="$C0" -v c1="$C1" '
function expand(s, set,   n, i, p, a, b, k, m) { n = split(s, p, ","); for (i = 1; i <= n; i++) { m = split(p[i], a, "-"); b = (m > 1) ? a[2] : a[1]; for (k = a[1]; k <= b; k++) set[k] = 1 } }
function avg10(file, kind,   line, f) { while ((getline line < file) > 0) if (index(line, kind) == 1) { split(line, f, " "); sub("avg10=", "", f[2]); close(file); return f[2] } close(file); return "NA" }
function stat(   line, f, id, tot, idle, k) {
  tb[0] = tb[1] = ib[0] = ib[1] = 0
  while ((getline line < "/proc/stat") > 0) if (line ~ /^cpu[0-9]/) { split(line, f, " "); id = substr(f[1], 4) + 0; tot = 0; for (k = 2; k <= 9; k++) tot += f[k]; idle = f[5] + f[6]
      g = (id in s0) ? 0 : ((id in s1) ? 1 : -1); if (g >= 0) { tb[g] += tot; ib[g] += idle } }
  close("/proc/stat") }
BEGIN {
  expand(c0, s0); expand(c1, s1); stat(); pt0 = tb[0]; pi0 = ib[0]; pt1 = tb[1]; pi1 = ib[1]; t = 0
  while (1) {
    system("sleep 0.5"); t += 0.5
    stat(); u0 = (tb[0] - pt0) ? 100 * (1 - (ib[0] - pi0) / (tb[0] - pt0)) : 0; u1 = (tb[1] - pt1) ? 100 * (1 - (ib[1] - pi1) / (tb[1] - pt1)) : 0
    pt0 = tb[0]; pi0 = ib[0]; pt1 = tb[1]; pi1 = ib[1]
    ma = "NA"; while ((getline line < "/proc/meminfo") > 0) if (line ~ /^MemAvailable:/) { split(line, f, " "); ma = f[2] } close("/proc/meminfo")
    fr = "NA"; getline fr < ("/sys/devices/system/cpu/cpu" cpu "/cpufreq/scaling_cur_freq"); close("/sys/devices/system/cpu/cpu" cpu "/cpufreq/scaling_cur_freq")
    printf "%.1f\t%s\t%s\t%s\t%s\t%s\t%s\t%.1f\t%.1f\t%s\n", t, avg10("/proc/pressure/cpu", "some"), avg10("/proc/pressure/memory", "some"), avg10("/proc/pressure/memory", "full"), avg10("/proc/pressure/io", "some"), avg10("/proc/pressure/io", "full"), ma, u0, u1, fr >> out
    fflush(out)
  }
}'
